```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <unordered_map>

using namespace std;

// Definimos un mapa para mapear los marcadores de Markdown a sus equivalentes en HTML
unordered_map<string, string> markdownToHtml {
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"* ", "<em>"},
    {"** ", "<strong>"},
    {"` ", "<code>"},
    {"[ ](", "<a href=''>"),
    {"](", "</a>")
};

// Función para convertir texto con formato Markdown a HTML
string convertMarkdownToHtml(string& markdown) {
    stringstream html;
    string marker, text;

    for (char c : markdown) {
        if (c == '\\') {
            html << c;
        } else if (c == '[') {
            html << markdownToHtml["[ ]("];
            marker = "";
        } else if (c == ']') {
            html << markdownToHtml[")"];
            markdown.erase(markdown.find_last_of("[") + 1, markdown.find_last_of("]"));
            html << markdown;
            markdown = "";
        } else if (c == '(') {
            marker += c;
        } else if (c == ')') {
            marker += c;
            if (markdownToHtml.count(marker)) {
                html << markdownToHtml[marker];
                marker = "";
            } else {
                html << c;
            }
        } else if (c == '#') {
            int count = 0;
            while (c == '#' && count < 6) {
                marker += c;
                c = markdown[++count];
            }
            html << markdownToHtml[marker];
            marker = "";
        } else if (c == '*' || c == '_' || c == '`') {
            int count = 1;
            char type = c;
            while (markdown[count] == type) {
                count++;
            }
            html << markdownToHtml[type + string(type, count - 1)];
            marker = "";
        } else {
            html << c;
        }
    }

    return html.str();
}

int main() {
    string markdown = "## Hola mundo\n"
                      "Este es un *texto* con **formato** markdown.\n"
                      "[Enlace](https://www.example.com/)\n"
                      "`Código`";

    string html = convertMarkdownToHtml(markdown);

    cout << "Markdown:\n" << markdown << "\n\n"
         << "HTML:\n" << html << endl;

    return 0;
}
```

La función `convertMarkdownToHtml` recibe una referencia a una cadena de texto con formato Markdown y devuelve una cadena de texto con formato HTML. El algoritmo de conversión se basa en un mapa que mapea los marcadores de Markdown a sus equivalentes en HTML. El código procesa el texto caracter por caracter, manteniendo una cadena de marcadores en curso para los enlaces y los marcadores de título. También utiliza la función `stringstream` para construir la cadena de texto HTML en tiempo de ejecución. Para los enlaces, el código extrae el texto entre los corchetes y lo inserta en el HTML. Para los marcadores de título, el código cuenta el número de '#' y mapea el marcador de título correspondiente en HTML. Para los marcados de formato, el código mapea el marcador de formato correspondiente en HTML. El código ignora los caracteres de escape y los caracteres especiales que no son marcadores de formato.

